import { test, expect } from '@playwright/test';

test.describe('Notification Panel Slide-in from Top', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display notification panel sliding in from top on first load', async ({ page }) => {
    // Verify notification panel is visible
    const notificationPanel = page.getByRole('region', { name: /notification panel/i });
    await expect(notificationPanel).toBeVisible();

    // Verify panel is positioned at the top
    const panelBoundingBox = await notificationPanel.boundingBox();
    expect(panelBoundingBox?.y).toBeLessThan(100);

    // Verify panel has correct height
    const panelHeight = await notificationPanel.evaluate((el) => el.offsetHeight);
    expect(panelHeight).toBeGreaterThan(200);

    // Verify panel is not hidden
    const isHidden = await notificationPanel.evaluate((el) => el.style.display === 'none');
    expect(isHidden).toBe(false);

    // Verify panel has slide-in animation class
    const hasSlideInClass = await notificationPanel.evaluate((el) => el.classList.contains('slide-in-from-top'));
    expect(hasSlideInClass).toBe(true);

    // Verify panel content is visible
    const message = page.getByText(/new notification/i);
    await expect(message).toBeVisible();
  });

  test('should hide notification panel when user clicks close button', async ({ page }) => {
    // Verify notification panel is visible
    const notificationPanel = page.getByRole('region', { name: /notification panel/i });
    await expect(notificationPanel).toBeVisible();

    // Verify close button is visible
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click close button
    await closeButton.click();

    // Verify notification panel is no longer visible
    await expect(notificationPanel).not.toBeVisible();

    // Verify panel has hidden class
    const isHidden = await notificationPanel.evaluate((el) => el.classList.contains('hidden'));
    expect(isHidden).toBe(true);

    // Verify close button is still present but disabled
    await expect(closeButton).toBeVisible();
    const isDisabled = await closeButton.evaluate((el) => el.disabled);
    expect(isDisabled).toBe(true);
  });
});
